package com.skyclone.mod.progression;

import com.google.gson.Gson;

import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * The module's data files (resources/data/progression/*.json, generated by
 * tools/gen/progression/gen_progression.py), as plain Gson classes. PURE: no Bukkit, so unit tests
 * parse the same files the server does.
 */
public final class Catalogs {

    private Catalogs() {}

    private static final Gson GSON = new Gson();

    public static <T> T read(Reader r, Class<T> type) { return GSON.fromJson(r, type); }

    // ---- levels.json -----------------------------------------------------------------------------

    public static final class LevelsFile {
        public int xpPerLevel = 100;
        public int healthPerLevel = 5;
        public int strengthEveryLevels = 5;
        public List<Reward> rewards = new ArrayList<>();
        public List<Emblem> emblems = new ArrayList<>();
        public List<Category> categories = new ArrayList<>();
        public int objectiveXp = 5;
        public int fairyExchangeXp = 10;
        public int bestiaryFamilyXp = 1;
        public int bestiaryMilestoneXp = 10;
    }

    /**
     * A level reward. {@code dial} (optional) names the feature's own gate dial (e.g. {@code bazaar.access-requirement});
     * when set, the level shown is the one that dial asks for ({@link PMath#gateLevel}), {@code level} being only the
     * fallback, so the list can never promise a feature at a different level than its gate opens it.
     */
    public static final class Reward {
        public int level; public String text; public String dial;
        public Reward() {}
        public Reward(int level, String text, String dial) { this.level = level; this.text = text; this.dial = dial; }
    }

    public static final class Emblem { public String id; public String name; public String symbol; public int level; }

    public static final class Category {
        public String id;
        public String name;
        public String icon;
        public int max;
        public List<Task> tasks = new ArrayList<>();
    }

    public static final class Task {
        public String name;
        public List<String> prefixes = new ArrayList<>();
        public int max;
    }

    // ---- bestiary.json -----------------------------------------------------------------------------

    public static final class BestiaryFile {
        public Map<String, List<Integer>> brackets;
        public List<BCategory> categories = new ArrayList<>();
    }

    public static final class BCategory {
        public String id;
        public String name;
        public String texture;
        public List<String> islands = new ArrayList<>();
        public List<Family> families = new ArrayList<>();
        /** Stat name (FARMING_FORTUNE, HUNTING_FORTUNE) this category's tiers pay instead of damage / Magic Find
         *  (research 08 6.1: the pest bestiary pays Farming Fortune); null for combat categories. */
        public String fortune;
    }

    public static final class Family {
        public String id;
        public String name;
        public String texture;
        public List<String> matchNames = new ArrayList<>();
        public List<String> neuMobs = new ArrayList<>();
        public int bracket = 2;
        public int cap = 1000;
        public int maxTier = 1;
    }

    // ---- museum.json -----------------------------------------------------------------------------

    public static final class MuseumFile {
        public List<String> stageOrder = new ArrayList<>();
        public List<MCategory> categories = new ArrayList<>();
    }

    public static final class MCategory {
        public String id;
        public String name;
        public String icon;
        public List<MEntry> entries = new ArrayList<>();
    }

    public static final class MEntry {
        public String id;
        public int xp;
        public String stage;
        public String skill;
        /** Lower-tier entry this one also counts for, or null. */
        public String child;
        /** Armour set pieces, or null for a single item. */
        public List<String> pieces;

        public boolean isSet() { return pieces != null && !pieces.isEmpty(); }

        /** The item ids this entry needs. */
        public List<String> ids() { return isSet() ? pieces : List.of(id); }
    }

    // ---- objectives.json -----------------------------------------------------------------------------

    public static final class ObjectivesFile { public List<ObjectiveDef> chain = new ArrayList<>(); }

    public static final class ObjectiveDef {
        public String id;
        public String text;
        public String hint;
        public int coins;
        public boolean skippable;
        public Trigger trigger = new Trigger();
    }

    /**
     * How an objective completes. {@code type}:
     * <ul>
     *   <li>{@code npc} - click an NPC whose anchor is in {@code anchors}</li>
     *   <li>{@code break} - break {@code amount} blocks of {@code materials} (vanilla BUILD zones) or get a
     *       {@code Gather} event of kind {@code gather} whose {@code what} contains one of {@code what}</li>
     *   <li>{@code have} - hold an item of one of {@code materials} (or sky ids in {@code what})</li>
     *   <li>{@code menu} - have a menu open whose title contains one of {@code title}</li>
     *   <li>{@code use_category} - right-click a block with an item of category {@code category} on {@code island}</li>
     *   <li>{@code island} - be on {@code island}</li>
     *   <li>{@code area} - stand in one of {@code areas} on {@code island}</li>
     *   <li>{@code kill} - kill {@code amount} sky mobs (optionally on {@code island} in {@code areas})</li>
     *   <li>{@code requirement} - {@code Sky.requirements().check(p, key)}</li>
     *   <li>{@code bank} - have coins in the bank</li>
     *   <li>{@code fairy_found} / {@code museum} - found souls / museum donations reach {@code amount}</li>
     * </ul>
     * Any type also accepts {@code commands} (typing one of them completes it) and {@code menu}
     * (a menu title containing one of them completes it), and every objective completes when another
     * module calls {@code Features.Objectives.complete(p, id)}.
     */
    public static final class Trigger {
        public String type = "manual";
        public List<String> anchors = new ArrayList<>();
        public List<String> materials = new ArrayList<>();
        public List<String> what = new ArrayList<>();
        public List<String> areas = new ArrayList<>();
        public List<String> title = new ArrayList<>();
        public List<String> menu = new ArrayList<>();
        public List<String> commands = new ArrayList<>();
        /** Zone ids (of {@link #island}) that complete this objective while the player stands in one; lets a
         *  "visit X" step finish at X instead of from a menu or command that opens X's screen from anywhere. */
        public List<String> zones = new ArrayList<>();
        public String gather;
        public String island;
        public String category;
        public String key;
        public int amount = 1;
    }

    // ---- island_guides.json ----------------------------------------------------------------------

    /** Per-island first-entry objective mini-chains (research 03 2.2). */
    public static final class GuidesFile { public List<IslandGuide> guides = new ArrayList<>(); }

    public static final class IslandGuide {
        public String id;
        public String island;
        public String name;
        public String icon;
        public int coins;
        public int sbxp = 5;
        public String about;
        public List<GuideStep> steps = new ArrayList<>();
    }

    public static final class GuideStep {
        public String text;
        public String hint;
        public Trigger trigger = new Trigger();
    }

    /** Trigger types an island guide step understands (IslandGuides). */
    public static final List<String> GUIDE_TRIGGER_TYPES = List.of("npc", "zone", "kill", "gather", "fish", "requirement");

    /** Trigger types the runtime understands (self-test + unit test check the data against it). */
    public static final List<String> TRIGGER_TYPES = List.of("npc", "break", "have", "menu", "use_category", "island",
            "area", "kill", "requirement", "bank", "fairy_found", "museum", "manual");
}
